WITH exploded AS (SELECT id, plan, EXPLODE_OUTER(discounts) AS tier_value FROM price_tiers) SELECT plan, CASE WHEN tier_value >= 66 THEN 'LARGE' ELSE 'SMALL' END AS tier_value_tier, AVG(tier_value) AS avg_tier_value, COUNT(DISTINCT plan) AS distinct_plans, MIN(tier_value) AS min_tier_value, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT id) AS distinct_ids_2, ROUND(AVG(tier_value), 2) AS avg_tier_value_2 FROM exploded GROUP BY plan, CASE WHEN tier_value >= 66 THEN 'LARGE' ELSE 'SMALL' END HAVING avg_tier_value > 0 ORDER BY avg_tier_value_2 DESC;
